import { useState } from "react";
import { useResults } from "../context/ResultsContext";
import { useNavigate } from "react-router-dom";
import { analyzeResumes } from "../api";

export default function UploadResumes() {
  const { setResults } = useResults();
  const navigate = useNavigate();
  const [files, setFiles] = useState([]);
  const [links, setLinks] = useState([]);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    files.forEach((f) => formData.append("resumes", f));
    links.forEach((l) => formData.append("github_links", l));

    setLoading(true);
    try {
      const data = await analyzeResumes(formData);
      setResults(data.results);
      navigate("/results");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="page-wrapper">
      <div className="container-fluid px-5">
        <h2>Upload Resumes</h2>

        <div className="theme-card">
          <form onSubmit={handleSubmit}>
            <input
              type="file"
              multiple
              accept=".pdf,.docx"
              onChange={(e) => {
                const f = Array.from(e.target.files);
                setFiles(f);
                setLinks(f.map(() => ""));
              }}
            />

            {files.map((f, i) => (
              <input
                key={i}
                placeholder="GitHub link (optional)"
                value={links[i]}
                onChange={(e) => {
                  const l = [...links];
                  l[i] = e.target.value;
                  setLinks(l);
                }}
              />
            ))}

            <button className="theme-btn mt-3" disabled={loading}>
              {loading ? "Analyzing..." : "Analyze Resumes"}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}
